function maxSubarrayLength(nums) {
  const stack = [];
  for (let left = 0; left < nums.length; left++) {
    if (stack.length === 0 || nums[left] > nums[stack[stack.length - 1]]) {
      stack.push(left);
    }
  }

  let best = 0;
  for (let right = nums.length - 1; right >= 0 && stack.length > 0; right--) {
    while (stack.length > 0 && nums[stack[stack.length - 1]] > nums[right]) {
      const left = stack.pop();
      best = Math.max(best, right - left + 1);
    }
  }
  return best;
}

