function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = 2000;
    const style = pick(0, 3);
    if (style === 0) return [Array.from({ length: n }, () => pick(-1000000000, 1000000000))];
    if (style === 1) return [Array.from({ length: n }, (_, i) => -1000000000 + i * 100000 + pick(0, 3000000))];
    if (style === 2) return [Array.from({ length: n }, (_, i) => -1000000000 + i * 1000)];
    return [Array.from({ length: n }, (_, i) => Math.floor(i / 50) * 10 + pick(0, 12))];
  }
  const n = pick(1, 9);
  const style = pick(0, 4);
  if (style === 0) return [Array.from({ length: n }, (_, i) => i + pick(0, 1))];
  if (style === 1) return [Array.from({ length: n }, () => pick(-1000000000, 1000000000))];
  return [Array.from({ length: n }, () => pick(-4, 4))];
}
